"use client";

import * as React from "react";
import { cn } from "../../lib/utils.js";

/**
 * Ranked-tier pyramid. Tiers stack top-to-bottom; each tier's width can
 * either grow toward the base ("widening" — Maslow's hierarchy, fewer
 * elites at the top) or shrink ("narrowing" — population pyramid by age).
 * Pure SVG; no heavy peer dependency.
 *
 * Distinct from Funnel: Pyramid encodes RANK (each tier is a distinct
 * categorical level), Funnel encodes FLOW (each stage is a subset of the
 * previous, with a conversion ratio).
 *
 * @example
 * <Pyramid
 *   tiers={[
 *     { id: "self-actualization", label: "Self-actualization" },
 *     { id: "esteem", label: "Esteem" },
 *     { id: "love", label: "Love & belonging" },
 *     { id: "safety", label: "Safety" },
 *     { id: "physiological", label: "Physiological" },
 *   ]}
 *   shape="widening"
 * />
 */
export type PyramidTier = {
	id: string;
	label: string;
	value?: number;
};

export interface PyramidProps extends Omit<React.SVGAttributes<SVGSVGElement>, "children"> {
	/** Ordered top-to-bottom tiers. The first entry is the apex. */
	tiers: PyramidTier[];
	/** Tier-width direction. "widening" grows toward the base; "narrowing" shrinks toward it. Default "widening". */
	shape?: "widening" | "narrowing";
	/** Pixel width of the rendered SVG. Default 480. */
	width?: number;
	/** Pixel height of the rendered SVG. Default 360. */
	height?: number;
	/** Pixel gap between tiers. Default 4. */
	gap?: number;
	/** Show each tier's `value` next to its label when present. Default true. */
	showValues?: boolean;
	/** Fired when a tier is clicked. */
	onTierClick?: (tier: PyramidTier) => void;
}

interface LaidOutTier {
	tier: PyramidTier;
	depth: number;
	topLeft: number;
	topRight: number;
	bottomLeft: number;
	bottomRight: number;
	yTop: number;
	yBottom: number;
}

function Pyramid({
	tiers,
	shape = "widening",
	width = 480,
	height = 360,
	gap = 4,
	showValues = true,
	onTierClick,
	className,
	...rest
}: PyramidProps) {
	const laidOut = layout(tiers, shape, width, height, gap);
	const desc = `Pyramid with ${tiers.length} tier${tiers.length === 1 ? "" : "s"} (${shape})`;

	// Pyramid's `whenNotToUse` warns about >7 tiers — surface a dev-only
	// console warning so consumers feel the friction in development without
	// punishing prod runtime. Uses a ref so the warning fires once per mount,
	// not on every render. Read NODE_ENV via globalThis to avoid pulling
	// `@types/node` into the components package — bundlers inline the value
	// in browser builds; in tests vitest/Node provides `process` at runtime.
	const warnedRef = React.useRef(false);
	const nodeEnv = (globalThis as { process?: { env?: { NODE_ENV?: string } } }).process?.env?.NODE_ENV;
	if (nodeEnv !== "production" && !warnedRef.current && tiers.length > 7) {
		warnedRef.current = true;
		// eslint-disable-next-line no-console
		console.warn(
			`[hex-core/Pyramid] ${tiers.length} tiers — labels become unreadable past ~7. Group adjacent tiers or switch to TreeMap / OrgChart.`,
		);
	}

	return (
		<svg
			{...rest}
			data-hex-pyramid
			data-shape={shape}
			role="img"
			width={width}
			height={height}
			viewBox={`0 0 ${width} ${height}`}
			className={cn("block", className)}
		>
			<title>Pyramid chart</title>
			<desc>{desc}</desc>
			<g data-hex-pyramid-tiers>
				{laidOut.map((t) => {
					const valueText =
						showValues && t.tier.value != null ? ` · ${t.tier.value.toLocaleString()}` : "";
					const interactive = Boolean(onTierClick);
					const handleActivate = () => onTierClick?.(t.tier);
					return (
						<g
							key={t.tier.id}
							data-hex-pyramid-tier
							data-depth={t.depth}
							role={interactive ? "button" : undefined}
							tabIndex={interactive ? 0 : undefined}
							aria-label={interactive ? `${t.tier.label}${valueText}` : undefined}
							style={interactive ? { cursor: "pointer" } : undefined}
							onClick={interactive ? handleActivate : undefined}
							onKeyDown={interactive ? (e) => activateOnKey(e, handleActivate) : undefined}
						>
							<polygon
								points={`${t.topLeft},${t.yTop} ${t.topRight},${t.yTop} ${t.bottomRight},${t.yBottom} ${t.bottomLeft},${t.yBottom}`}
								fill="hsl(var(--primary))"
								// Floor at 0.6 keeps `primary-foreground` text on the tier
								// at ≥4.5:1 contrast even at the widest pyramids.
								fillOpacity={Math.max(0.6, 1 - t.depth * 0.07)}
								stroke="hsl(var(--background))"
								strokeWidth={1}
							/>
							<text
								x={width / 2}
								y={(t.yTop + t.yBottom) / 2}
								dy="0.35em"
								textAnchor="middle"
								fontSize={12}
								fontWeight={600}
								fill="hsl(var(--primary-foreground))"
								style={{ pointerEvents: "none" }}
							>
								{`${t.tier.label}${valueText}`}
							</text>
						</g>
					);
				})}
			</g>
		</svg>
	);
}

function layout(
	tiers: PyramidTier[],
	shape: "widening" | "narrowing",
	width: number,
	height: number,
	gap: number,
): LaidOutTier[] {
	if (tiers.length === 0) return [];
	const usableHeight = height - gap * Math.max(0, tiers.length - 1);
	const tierHeight = usableHeight / tiers.length;
	const cx = width / 2;
	const total = tiers.length;

	// Linear ramp: top tier ratio 0.2, bottom tier ratio 1.0 (or reverse).
	const ratioAt = (i: number): number => {
		const t = total === 1 ? 0 : i / (total - 1);
		return shape === "widening" ? 0.2 + 0.8 * t : 1.0 - 0.8 * t;
	};

	return tiers.map((tier, i) => {
		const yTop = i * (tierHeight + gap);
		const yBottom = yTop + tierHeight;
		const topRatio = ratioAt(i);
		const bottomRatio = i + 1 < total ? ratioAt(i + 1) : topRatio;
		// For widening, the visual base of each tier should match the top of
		// the next tier — using the next tier's ratio at the bottom edge.
		// For narrowing, same logic. The penultimate-to-last bottom matches
		// `topRatio` of the last tier we don't have, so we hold steady.
		const topHalfWidth = (width / 2) * topRatio;
		const bottomHalfWidth = (width / 2) * bottomRatio;
		return {
			tier,
			depth: i,
			topLeft: cx - topHalfWidth,
			topRight: cx + topHalfWidth,
			bottomLeft: cx - bottomHalfWidth,
			bottomRight: cx + bottomHalfWidth,
			yTop,
			yBottom,
		};
	});
}

function activateOnKey(e: React.KeyboardEvent, fn: () => void): void {
	if (e.key === "Enter" || e.key === " ") {
		e.preventDefault();
		fn();
	}
}

export { Pyramid };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex UI: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}
